use knownext_storage::LocalApi;
use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::fs;
fn hash(bytes:&[u8])->String{format!("{:x}",Sha256::digest(bytes))}
#[test]
fn conflict_roles_come_from_verified_matching_manifests_and_recovery_keeps_every_copy(){
 let owned=tempfile::tempdir().unwrap();let state=owned.path().join("state");let api=LocalApi::new(state.clone(),"qa".into(),"test".into());let project=api.handle("POST","/api/projects",json!({"name":"Owned conflict groups","versioningMode":"none","syncMode":"none"}),vec![]).unwrap().body;let id=format!("{}::Owned.md",project["id"].as_str().unwrap());let mut originals=vec![];
 for(index,(side,text))in [("conflict-local","My edition"),("conflict-disk","Disk edition"),("conflict-proposed","Combined"),("conflict-remote-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","Known remote")].into_iter().enumerate(){let key=format!("recovery-owned-{index}");let folder=state.join("drafts-review").join(&key);fs::create_dir_all(&folder).unwrap();let bytes=serde_json::to_vec(&json!({"documentId":id,"markdown":text})).unwrap();let manifest=serde_json::to_vec(&json!({"schemaVersion":1,"id":key,"sourceKey":format!("v2_{}",hash(id.as_bytes())),"fingerprint":hash(&bytes),"bytes":bytes.len(),"archivedAt":"2026-11-02T00:00:00Z","retention":"manual-no-auto-expiry","operationId":"conflict-owned","reason":side})).unwrap();fs::write(folder.join("copy.json"),&bytes).unwrap();fs::write(folder.join("manifest.json"),&manifest).unwrap();originals.push((folder,bytes,manifest));}
 let inventory=api.handle("GET","/api/recovery/archives",Value::Null,vec![]).unwrap().body;let rows=inventory["items"].as_array().unwrap();assert_eq!(rows.len(),4);for role in ["local","disk","proposal","remote"]{assert_eq!(rows.iter().filter(|row|row["variantRole"]==role&&row["operationId"]=="conflict-owned").count(),1);}
 let remote=rows.iter().find(|row|row["variantRole"]=="remote").unwrap();let result=api.handle("POST",&format!("/api/recovery/drafts/{}/copy",remote["key"].as_str().unwrap()),json!({"source":"archive","fingerprint":remote["fingerprint"],"projectId":project["id"],"name":"Recovered.md"}),vec![]).unwrap();assert!(result.status<400);assert_eq!(fs::read_to_string(std::path::Path::new(project["folderPath"].as_str().unwrap()).join("Recovered.md")).unwrap(),"Known remote");for(folder,bytes,manifest)in &originals{assert_eq!(fs::read(folder.join("copy.json")).unwrap(),*bytes);assert_eq!(fs::read(folder.join("manifest.json")).unwrap(),*manifest);}
 let(folder,_,manifest)=&originals[0];let mut future:Value=serde_json::from_slice(manifest).unwrap();future["futureInstruction"]=json!(true);let future=serde_json::to_vec(&future).unwrap();fs::write(folder.join("manifest.json"),&future).unwrap();let changed=api.handle("GET","/api/recovery/archives",Value::Null,vec![]).unwrap().body;let changed=changed["items"].as_array().unwrap().iter().find(|row|row["key"]=="recovery-owned-0").unwrap();assert_eq!(changed["canCopy"],false);assert!(changed["operationId"].is_null());assert!(changed["variantRole"].is_null());assert_eq!(fs::read(folder.join("manifest.json")).unwrap(),future);
 let mut foreign:Value=serde_json::from_slice(manifest).unwrap();foreign["sourceKey"]=json!(format!("v2_{}","0".repeat(64)));fs::write(folder.join("manifest.json"),serde_json::to_vec(&foreign).unwrap()).unwrap();let changed=api.handle("GET","/api/recovery/archives",Value::Null,vec![]).unwrap().body;let row=changed["items"].as_array().unwrap().iter().find(|row|row["key"]=="recovery-owned-0").unwrap();assert!(row["operationId"].is_null());assert!(row["variantRole"].is_null());
}
